fixedSource: |
  int[] limits = { 100, 500, 1000 };
  PriceTiers tiers = new PriceTiers(limits);
  limits[0] = 2000;
  Console.WriteLine(tiers.IsSorted());

  class PriceTiers
  {
      private readonly int[] _limits;

      public PriceTiers(int[] limits)
      {
          int[] copy = limits.ToArray();
          for (int i = 1; i < copy.Length; i++)
          {
              if (copy[i - 1] >= copy[i])
              {
                  throw new ArgumentException("Limits must be sorted.");
              }
          }

          _limits = copy;
      }

      public bool IsSorted()
      {
          for (int i = 1; i < _limits.Length; i++)
          {
              if (_limits[i - 1] >= _limits[i])
              {
                  return false;
              }
          }

          return true;
      }
  }
fixedExpect: { kind: output, value: "True" }
